{"implementation":"def solve(case):
    import collections
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    if not nodes:
        raise ValueError("No nodes")
    node_by_id = {n["id"]: n for n in nodes}
    roots = [n for n in nodes if n["parent"] is None]
    if len(roots) != 1:
        raise ValueError("Must have exactly one root")
    for n in nodes:
        if n["parent"] is not None and n["parent"] not in node_by_id:
            raise ValueError("Parent not found")
    symbols_present = {n["symbol"] for n in nodes}
    for sym in required_symbols:
        if sym not in symbols_present:
            raise ValueError("Required symbol missing")
    children = collections.defaultdict(list)
    for n in nodes:
        if n["parent"] is not None:
            children[n["parent"]].append(n["id"])
    retained = {n["id"] for n in nodes}
    symbol_counts = collections.Counter(n["symbol"] for n in nodes)
    removed = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))
    for node in sorted_nodes:
        nid = node["id"]
        if not node["removable"]:
            continue
        if node["parent"] is None:
            continue
        if node["symbol"] in required_symbols:
            continue
        if any(child in retained for child in children.get(nid, [])):
            continue
        removed.append(nid)
        retained.remove(nid)
        symbol_counts[node["symbol"]] -= 1
    retained_sorted = sorted(retained)
    return {
        "removed_node_ids": removed,
        "retained_node_ids": retained_sorted
    }"}
